    { const char * tb_v1430 = "    tb_gpage ***d = &tb_gdir[a >> 32];\n"; *(const char * *)tb_grow(v_lines) = tb_v1430; }
    { const char * tb_v1431 = "    if (!*d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1431; }
    { const char * tb_v1432 = "        *d = calloc(1 << 16, sizeof(tb_gpage *));\n"; *(const char * *)tb_grow(v_lines) = tb_v1432; }
    { const char * tb_v1433 = "        if (!*d) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1433; }
    { const char * tb_v1434 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1434; }
    { const char * tb_v1435 = "    (*d)[(a >> TB_GSH) & 0xFFFF] = pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v1435; }
    { const char * tb_v1436 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1436; }
    { const char * tb_v1437 = "TB_API void tb_gmap_add(tb_gpage *pg, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1437; }
    { const char * tb_v1438 = "    for (long long o = 0; o < size; o += TB_GPG) tb_gmap_put((uintptr_t)pg->start + o, pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v1438; }
    { const char * tb_v1439 = "    if ((uintptr_t)pg->start < tb_glo) tb_glo = (uintptr_t)pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v1439; }
