    { const char * tb_v2589 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2589; }
    { const char * tb_v2590 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2590; }
    { const char * tb_v2591 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2591; }
    { const char * tb_v2592 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v2592; }
    { const char * tb_v2593 = "        return o < (unsigned long long)d->npos ? d->pos[o] - 1 : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2593; }
    { const char * tb_v2594 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2594; }
    { const char * tb_v2595 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2595; }
    { const char * tb_v2596 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v2596; }
    { const char * tb_v2597 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2597; }
    { const char * tb_v2598 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2598; }
