    { const char * tb_v2603 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2603; }
    { const char * tb_v2604 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v2604; }
    { const char * tb_v2605 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2605; }
    { const char * tb_v2606 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2606; }
    { const char * tb_v2607 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2607; }
    { const char * tb_v2608 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v2608; }
